with lines as (select id, log_ts, latency_ms, status_code, k, attr_value from app_logs lateral view explode(context) t as k, attr_value) select k, case when latency_ms >= 1914 then 'LARGE' else 'SMALL' end as latency_ms_tier, date_trunc('hour', log_ts) as hour_window, bit_or(latency_ms) as latency_ms_bit_or, min(log_ts) as first_seen, approx_percentile(latency_ms, array(0.25, 0.5, 0.75)) as latency_ms_quartiles, min(log_ts) as started_at, grouping(k) as gid from lines group by grouping sets ((k, case when latency_ms >= 1914 then 'LARGE' else 'SMALL' end, date_trunc('hour', log_ts)), (k, case when latency_ms >= 1914 then 'LARGE' else 'SMALL' end), (k)) order by k desc;
